#!/usr/bin/env bash
# test-e2e-pwa-config.sh — checks the PWA e2e daemon config generated by
# scripts/e2e-pwa-config.sh (e2e_pwa_write_config).
#
# The generated config must allow the parent of the run dir as a project
# root (the PWA stories seed sessions there), carry the passed ports, token
# and loopback host, and keep data_dir under the run dir. The production
# template testdata/datawatch.yaml must never carry allowed_project_roots.
set -u

ROOT=$(git rev-parse --show-toplevel) || { echo "FAIL: not in a git repository" >&2; exit 1; }
TMPL="$ROOT/testdata/datawatch.yaml"
HELPER="$ROOT/scripts/e2e-pwa-config.sh"

SANDBOX=$(mktemp -d)
RUN_DIR="$SANDBOX/dw-e2e-pwa-test"
mkdir -p "$RUN_DIR"
trap 'rm -rf "$SANDBOX"' EXIT

fail() { echo "FAIL: $*" >&2; exit 1; }

[ -f "$HELPER" ] || fail "helper not found: $HELPER"
[ -f "$TMPL" ] || fail "template not found: $TMPL"

# shellcheck source=../scripts/e2e-pwa-config.sh
. "$HELPER"
declare -F e2e_pwa_write_config >/dev/null || fail "e2e_pwa_write_config not defined by $HELPER"

OUT="$RUN_DIR/config.yaml"
# Signature: e2e_pwa_write_config TMPL OUT RUN_DIR HTTP_PORT TLS_PORT SSE_PORT TOKEN
e2e_pwa_write_config "$TMPL" "$OUT" "$RUN_DIR" 8081 8441 9091 test-token \
  || fail "e2e_pwa_write_config returned non-zero"
[ -s "$OUT" ] || fail "generated config is missing or empty: $OUT"

# allowed_project_roots line names the sandbox (parent of the run dir).
roots_line=$(grep -E '^  allowed_project_roots:' "$OUT") \
  || fail "generated config has no '  allowed_project_roots:' line"
case "$roots_line" in
  *"$SANDBOX"*) ;;
  *) fail "allowed_project_roots line does not contain $SANDBOX: $roots_line" ;;
esac

grep -Eq '^[[:space:]]*port: 8081([[:space:]]|$)' "$OUT" || fail "port: 8081 not found"
grep -Eq '^[[:space:]]*tls_port: 8441([[:space:]]|$)' "$OUT" || fail "tls_port: 8441 not found"
grep -Eq '^[[:space:]]*sse_port: 9091([[:space:]]|$)' "$OUT" || fail "sse_port: 9091 not found"
grep -Fq 'token: "test-token"' "$OUT" || fail "passed token test-token not found"
grep -Eq '^[[:space:]]*host: 127\.0\.0\.1([[:space:]]|$)' "$OUT" || fail "host: 127.0.0.1 not found"
grep -Fq "data_dir: $RUN_DIR/" "$OUT" || fail "data_dir is not under $RUN_DIR"

# The production template must never pick up a default project root.
if grep -Ev '^[[:space:]]*#' "$TMPL" | grep -q 'allowed_project_roots'; then
  fail "testdata/datawatch.yaml contains allowed_project_roots"
fi

echo "OK: generated e2e PWA config allows $SANDBOX as project root"
exit 0
